        resp = JSON.parse(req.Get(query));

    if (req.Status() != 200 || !resp.ok || resp.ok === ''false'') {
        throw ''message was created, but getting message link was failed with reason "'' + resp.error + ''"'';
    }

    return resp.permalink;
}

