INSERT INTO triggers (triggerid,expression,description,url,status,priority,comments,templateid,type,flags,recovery_mode,recovery_expression,correlation_mode,correlation_tag,manual_close,opdata,discover) values ('17149','{20156} > {$MSSQL.PERCENT_READAHEAD.MAX} / 100 * {20157}','MSSQL: Too many physical reads occurring','','0','2','If this value makes up even a sizeable minority of the total Page Reads/sec (say, greater than 20% of the total page reads), you may have too many physical reads occurring.',NULL,'0','0','0','','0','','0','','0');
INSERT INTO triggers (triggerid,expression,description,url,status,priority,comments,templateid,type,flags,recovery_mode,recovery_expression,correlation_mode,correlation_tag,manual_close,opdata,discover) values ('17150','{20158} > {$MSSQL.PERCENT_COMPILATIONS.MAX}','MSSQL: Percent of adhoc queries running is over {$MSSQL.PERCENT_COMPILATIONS.MAX}% for 15m','','0','2','The lower this value is the better. High values often indicate excessive adhoc querying and should be as low as possible. If excessive adhoc querying is happening, try rewriting the queries as procedures or invoke the queries using sp_executeSQL. When rewriting isn''t possible, consider using a plan guide or setting the database to parameterization forced mode.',NULL,'0','0','0','','0','','0','','0');
INSERT INTO triggers (triggerid,expression,description,url,status,priority,comments,templateid,type,flags,recovery_mode,recovery_expression,correlation_mode,correlation_tag,manual_close,opdata,discover) values ('17151','{20159} > {$MSSQL.PERCENT_RECOMPILATIONS.MAX}','MSSQL: Percent of times statement recompiles is over {$MSSQL.PERCENT_RECOMPILATIONS.MAX}% for 15m','','0','2','This number should be at or near zero, since recompiles can cause deadlocks and exclusive compile locks. This counter''s value should follow in proportion to “Batch Requests/sec” and “SQL Compilations/sec”.',NULL,'0','0','0','','0','','0','','0');
INSERT INTO triggers (triggerid,expression,description,url,status,priority,comments,templateid,type,flags,recovery_mode,recovery_expression,correlation_mode,correlation_tag,manual_close,opdata,discover) values ('17153','{20161}=0','MSSQL: Service is unavailable','','0','5','The TCP port of the MS SQL Server service is currently unavailable.',NULL,'0','0','0','','0','','0','','0');
