INSERT INTO triggers (triggerid,expression,description,url,status,priority,comments,templateid,type,flags,recovery_mode,recovery_expression,correlation_mode,correlation_tag,manual_close,opdata,discover) values ('17155','{20164} * 100 / {20165} > {$ORACLE.SESSIONS.MAX.WARN}','Oracle: Too many active sessions (over {$ORACLE.SESSIONS.MAX.WARN}% for 5 min)','','0','2','Active sessions are using more than {$ORACLE.SESSIONS.MAX.WARN}% of the available sessions.',NULL,'0','0','0','','0','','0','','0');
